local function connect(signal, callback)
    local c = signal:Connect(callback)
    table.insert(connections, c)
    return c
end

local function round(obj, pixels)
    Instance.new("UICorner", obj).CornerRadius = UDim.new(0, pixels)
    return obj
end

local function stroke(obj, color, transparency)
    local s = Instance.new("UIStroke")
    s.Color = color or C.stroke
    s.Thickness = 1
    s.Transparency = transparency or 0
    s.Parent = obj
    return s
end

local function make(className, props, parent)
    local object = Instance.new(className)
    for k, v in pairs(props or {}) do
        object[k] = v
    end
    object.Parent = parent
    return object
end

local function textLabel(parent, value, size, color, bold)
    return make("TextLabel", {
        BackgroundTransparency = 1,
        Text = value,
        Font = bold and Enum.Font.GothamBold or Enum.Font.Gotham,
        TextSize = size,
        TextColor3 = color or C.text,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextYAlignment = Enum.TextYAlignment.Center,
        TextTruncate = Enum.TextTruncate.AtEnd,
    }, parent)
end

local function tween(object, props, duration)
    local t = TweenService:Create(object, TweenInfo.new(duration or 0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), props)
    t:Play()
    return t
end

local function loadConfig()
    if type(isfile) ~= "function" or type(readfile) ~= "function" then return end
    local ok, data = pcall(function()
        if not isfile(CONFIG_NAME) then return nil end
        return HttpService:JSONDecode(readfile(CONFIG_NAME))
    end)
    if ok and type(data) == "table" then
        for k, defaultValue in pairs(settings) do
            if not ({autoFarm=true,autoBoss=true,autoChest=true,autoFruit=true,autoRaid=true,autoAura=true,autoInstinct=true,autoStats=true})[k]
                and type(data[k]) == type(defaultValue) then
                settings[k] = data[k]
            end
        end
    end
    -- Nunca liga o farm automaticamente apos carregar o arquivo.
    settings.autoFarm = false
    settings.autoBoss = false
    settings.autoChest = false
    settings.autoFruit = false
    settings.autoRaid = false
    settings.autoAura = false
    settings.autoInstinct = false
    settings.autoStats = false
end

local function saveConfig()
    if not settings.autoSave or type(writefile) ~= "function" then return end
    local data = {}
    for name, value in pairs(settings) do
        if not ({autoFarm=true,autoBoss=true,autoChest=true,autoFruit=true,autoRaid=true,autoAura=true,autoInstinct=true,autoStats=true})[name]
            and (type(value) == "string" or type(value) == "boolean" or type(value) == "number") then
            data[name] = value
        end
    end
    pcall(function() writefile(CONFIG_NAME, HttpService:JSONEncode(data)) end)
end

loadConfig()

