if type(gethui) == "function" then
    local ok, result = pcall(gethui)
    if ok and typeof(result) == "Instance" then parentGui = result end
else
    local canUseCoreGui = pcall(function() return CoreGui:GetChildren() end)
    if canUseCoreGui then parentGui = CoreGui end
end
pcall(function()
    local candidate = parentGui:FindFirstChild(GUI_NAME)
    if candidate then candidate:Destroy() end
end)
local oldGui = player.PlayerGui:FindFirstChild(GUI_NAME)
if oldGui then oldGui:Destroy() end

