    Name = GUI_NAME,
    ResetOnSpawn = false,
    IgnoreGuiInset = true,
    ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
    DisplayOrder = 50,
}, nil)
local mounted = pcall(function() gui.Parent = parentGui end)
if not mounted then gui.Parent = player.PlayerGui end

local function clearESP()
    for target, record in pairs(espRecords) do
        for _, instance in ipairs(record.instances) do
            pcall(function() instance:Destroy() end)
        end
        espRecords[target] = nil
    end
end

local function stop()
    if not alive then return end
    alive = false
    settings.autoFarm = false
    clearESP()
    for _, c in ipairs(connections) do pcall(function() c:Disconnect() end) end
    pcall(function() gui:Destroy() end)
    if type(_G.FrioHubBF) == "table" then
        _G.FrioHubBF = nil
    end
end
_G.FrioHubBF = { Stop = stop }

