local function createPage(id, heading, description)
    local page = make("Frame", {
        Name = id,
        Size = UDim2.fromScale(1, 1),
        BackgroundTransparency = 1,
        Visible = false,
    }, content)
    local headingText = textLabel(page, heading, 18, C.text, true)
    headingText.Position = UDim2.fromOffset(19, 10)
    headingText.Size = UDim2.new(1, -32, 0, 28)
    local descriptionText = textLabel(page, description, 11, C.muted, false)
    descriptionText.Position = UDim2.fromOffset(19, 37)
    descriptionText.Size = UDim2.new(1, -32, 0, 19)
    local scroll = make("ScrollingFrame", {
        Position = UDim2.fromOffset(15, 64),
        Size = UDim2.new(1, -30, 1, -70),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ScrollBarThickness = 3,
        ScrollBarImageColor3 = C.accent2,
        CanvasSize = UDim2.new(),
        AutomaticCanvasSize = Enum.AutomaticSize.Y,
    }, page)
    make("UIListLayout", {
        Padding = UDim.new(0, 10),
        SortOrder = Enum.SortOrder.LayoutOrder,
    }, scroll)
    make("UIPadding", { PaddingBottom = UDim.new(0, 10) }, scroll)
    pages[id] = page
    return scroll
end

local function selectPage(id)
    selectedTab = id
    for key, page in pairs(pages) do
        page.Visible = key == id
    end
    for key, button in pairs(navButtons) do
        local active = key == id
        tween(button, {BackgroundColor3 = active and C.raised2 or C.panel})
        button.TextColor3 = active and C.accent or C.muted
    end
end

local function navigation(id, name, icon)
