        Font = Enum.Font.GothamSemibold,
        TextSize = 12,
        TextColor3 = C.muted,
        TextXAlignment = Enum.TextXAlignment.Left,
        AutoButtonColor = false,
    }, sidebar), 10)
    navButtons[id] = btn
    connect(btn.MouseButton1Click, function() selectPage(id) end)
end

