local toggleControls = {}
local function syncToggles()
    for name, controls in pairs(toggleControls) do
        for _, control in ipairs(controls) do
            local enabled = settings[name]
            control.button.BackgroundColor3 = enabled and C.accent2 or C.raised2
            control.dot.Position = UDim2.fromOffset(enabled and 29 or 4, 4)
            control.dot.BackgroundColor3 = enabled and C.text or C.muted
        end
    end
end
local function toggleRow(parent, heading, description, settingName, onChanged)
    local f = card(parent, 72)
    local label = textLabel(f, heading, 12, C.text, true)
    label.Position = UDim2.fromOffset(13, 8)
    label.Size = UDim2.new(1, -85, 0, 23)
    local sub = textLabel(f, description, 10, C.muted)
    sub.Position = UDim2.fromOffset(13, 33)
    sub.Size = UDim2.new(1, -88, 0, 28)
    sub.TextWrapped = true

    local button = round(make("TextButton", {
        AnchorPoint = Vector2.new(1, 0.5),
        Position = UDim2.new(1, -13, 0.5, 0),
        Size = UDim2.fromOffset(52, 27),
        BackgroundColor3 = settings[settingName] and C.accent2 or C.raised2,
        BorderSizePixel = 0,
        Text = "",
        AutoButtonColor = false,
    }, f), 20)
    local dot = round(make("Frame", {
        Position = UDim2.fromOffset(settings[settingName] and 29 or 4, 4),
        Size = UDim2.fromOffset(19, 19),
        BackgroundColor3 = settings[settingName] and C.text or C.muted,
        BorderSizePixel = 0,
    }, button), 20)
    connect(button.MouseButton1Click, function()
        if not alive then return end
        settings[settingName] = not settings[settingName]
        local enabled = settings[settingName]
        if enabled and ({autoFarm=true, autoBoss=true, autoChest=true,
            autoFruit=true, autoRaid=true})[settingName] then
            for _, category in ipairs({"autoFarm", "autoBoss", "autoChest", "autoFruit", "autoRaid"}) do
                if category ~= settingName then settings[category] = false end
            end
        end
        syncToggles()
        if onChanged then onChanged(enabled) end
        saveConfig()
    end)
    toggleControls[settingName] = toggleControls[settingName] or {}
    table.insert(toggleControls[settingName], {button=button, dot=dot})
    return f, button, dot
end

