local function findTool(category)
    for _, container in ipairs({player.Backpack, player.Character}) do
        if container then
            for _, tool in ipairs(container:GetChildren()) do
                if tool:IsA("Tool") then
                    local tooltip = tool.ToolTip or ""
                    local matches = tooltip == category
                        or (category == "Blox Fruit" and (tooltip == "Fruit" or tool.Name:find("Fruit")))
                    if matches then return tool end
                end
            end
        end
    end
    return nil
end

local function equipSelected()
    local character = player.Character
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    local tool = findTool(settings.category)
    if humanoid and tool then
        pcall(function() humanoid:EquipTool(tool) end)
        return true
    end
    return false
end

local toastText
local function notify(message)
    if toastText then
        toastText.Text = message
        task.delay(3, function()
            if alive and toastText and toastText.Text == message then
                toastText.Text = ""
            end
        end)
    end
end

