    local options = {"Melee", "Defense", "Sword", "Gun", "Demon Fruit"}
    for i, value in ipairs(options) do
        if value == settings.statCategory then
            settings.statCategory = options[i % #options + 1]
            notify("Distribuicao: " .. settings.statCategory)
            saveConfig()
            return
        end
    end
    settings.statCategory = options[1]
end)

