connect(close.MouseButton1Click, function()
    if _G.FrioHubBF and type(_G.FrioHubBF.Stop) == "function" then _G.FrioHubBF.Stop() end
end)

local function draggable(object, handle, onEnd)
    local dragging = false
    local dragStart, original, inputObject
    local moved = false
    connect(handle.InputBegan, function(input)
        if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then
            return
        end
        dragging = true
        moved = false
        dragStart = input.Position
        original = object.Position
        inputObject = input
    end)
    connect(UserInputService.InputEnded, function(input)
        if dragging and (input == inputObject or (inputObject and inputObject.UserInputType == Enum.UserInputType.MouseButton1 and input.UserInputType == Enum.UserInputType.MouseButton1)) then
            dragging = false
            if onEnd then onEnd(moved) end
        end
    end)
    connect(UserInputService.InputChanged, function(input)
        if not dragging then return end
        if input ~= inputObject and input.UserInputType ~= Enum.UserInputType.MouseMovement then
            return
        end
        local delta = input.Position - dragStart
        if delta.Magnitude > 7 then moved = true end
        object.Position = UDim2.new(
            original.X.Scale, original.X.Offset + delta.X,
            original.Y.Scale, original.Y.Offset + delta.Y
        )
    end)
end

draggable(main, header)
local orbDragged = false
draggable(orb, orb, function(moved) orbDragged = moved end)
connect(orb.MouseButton1Click, function()
    if orbDragged then
        orbDragged = false
        return
    end
    setMinimized(false)
end)
connect(UserInputService.InputBegan, function(input, consumed)
    if consumed then return end
    if input.KeyCode == Enum.KeyCode.RightControl then
        setMinimized(main.Visible)
    end
end)

local function resize()
    local camera = workspace.CurrentCamera
    if not camera then return end
    local view = camera.ViewportSize
    main.Size = UDim2.fromOffset(math.max(280, math.min(720, view.X - 22)), math.max(260, math.min(440, view.Y - 24)))
    local sidebarWidth = view.X < 580 and 116 or 155
    sidebar.Size = UDim2.new(0, sidebarWidth, 1, -106)
    content.Position = UDim2.fromOffset(sidebarWidth, 72)
    content.Size = UDim2.new(1, -sidebarWidth, 1, -106)
end
resize()
if workspace.CurrentCamera then
    connect(workspace.CurrentCamera:GetPropertyChangedSignal("ViewportSize"), resize)
end

local function compactNumber(value)
    value = tonumber(value)
    if not value then return "--" end
    if value >= 1000000000 then return string.format("%.1fB", value / 1e9) end
    if value >= 1000000 then return string.format("%.1fM", value / 1e6) end
    if value >= 1000 then return string.format("%.1fK", value / 1e3) end
    return tostring(math.floor(value))
end
local function readData(name)
    local data = player:FindFirstChild("Data")
    local obj = data and data:FindFirstChild(name)
    return obj and obj.Value or nil
end
