-- Reconhecimento de ESP local (sem rotas de rede).
local function classify(target)
    local name = target.Name:lower()
    if settings.fruitESP and target:IsA("Tool") and name:find("fruit", 1, true) then
        return "FRUTA", C.mint
    end
    if settings.chestESP and target:IsA("BasePart") and name:find("chest", 1, true) then
        return "BAÚ", C.accent
    end
    if settings.bossESP and target:IsA("Model") and name:find("boss", 1, true) then
        local folder = workspace:FindFirstChild("Enemies")
        if folder and target:IsDescendantOf(folder) then return "BOSS", C.danger end
    end
    if settings.playerESP and target:IsA("Model") then
        local targetPlayer = Players:GetPlayerFromCharacter(target)
        if targetPlayer and targetPlayer ~= player then return "JOGADOR", C.accent2 end
    end
    if settings.npcESP and target:IsA("Model") then
        local enemies = workspace:FindFirstChild("Enemies")
        if enemies and target:IsDescendantOf(enemies) then return "NPC", C.muted end
    end
    return nil
end
local function findPart(target)
    if target:IsA("BasePart") then return target end
    if target:IsA("Model") then
        return target:FindFirstChild("HumanoidRootPart") or target.PrimaryPart or target:FindFirstChildWhichIsA("BasePart", true)
    end
    if target:IsA("Tool") then return target:FindFirstChild("Handle") end
    return nil
end

local function mark(target, category, color)
    local part = findPart(target)
    if not part then return end
    local bill = make("BillboardGui", {
        Name = "FrioHubESP",
        Adornee = part,
        AlwaysOnTop = true,
        StudsOffsetWorldSpace = Vector3.new(0, 3.3, 0),
        Size = UDim2.fromOffset(118, 25),
        MaxDistance = 1800,
    }, gui)
    local bubble = round(make("Frame", {
        Size = UDim2.fromScale(1, 1),
        BackgroundColor3 = C.panel,
        BackgroundTransparency = 0.08,
        BorderSizePixel = 0,
    }, bill), 7)
    stroke(bubble, color, 0.1)
    local tag = textLabel(bubble, category .. " • " .. target.Name, 10, color, true)
    tag.Position = UDim2.fromOffset(5, 0)
    tag.Size = UDim2.new(1, -10, 1, 0)
    tag.TextXAlignment = Enum.TextXAlignment.Center
    local instances = {bill}
    if settings.highlightESP and (target:IsA("Model") or target:IsA("BasePart")) then
        local h = Instance.new("Highlight")
        h.Name = "FrioHubHighlight"
        h.Adornee = target
        h.FillColor = color
        h.OutlineColor = C.text
        h.FillTransparency = 0.75
        h.OutlineTransparency = 0.3
        h.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
        h.Parent = gui
        table.insert(instances, h)
    end
    espRecords[target] = {instances = instances, category = category}
end

local function refreshESP()
    for target, record in pairs(espRecords) do
        local actualCategory = target.Parent and classify(target)
        if actualCategory ~= record.category then
            for _, instance in ipairs(record.instances) do pcall(function() instance:Destroy() end) end
            espRecords[target] = nil
        end
    end
    if not (settings.fruitESP or settings.chestESP or settings.bossESP
        or settings.playerESP or settings.npcESP) then return end
    local maxTargets, added = 75, 0
    -- Um teto de varredura limita consumo em mapas grandes.
    local scanned = 0
    for _, target in ipairs(workspace:GetDescendants()) do
        scanned = scanned + 1
        if scanned > 8000 or added >= maxTargets then break end
        if target:IsA("Tool") or target:IsA("Model") or target:IsA("BasePart") then
            local category, color = classify(target)
            if category then
                added = added + 1
                if not espRecords[target] then mark(target, category, color) end
            end
        end
    end
end

