local MAX_FARM_LEVEL = 2800
local farmState = {message = "Inativo", retryAt = 0, lastSeaNotice = 0, lastQuestNotice = 0,
    target = nil, stuckPos = nil, stuckAt = 0}
local function questForLevel(lv)
    local n = math.floor(tonumber(lv) or 1)
    if n < 1 or n >= MAX_FARM_LEVEL then return nil end
    local stage = QUEST_BY_LEVEL[n]
    return stage and QUESTS[stage.questIndex] or nil
end
local function getWorldFromLevel(lv)
    if lv < 700 then return 1 end
    if lv < 1500 then return 2 end
    return 3
end
local seaByPlace = {[2753915549]=1, [4442272183]=2, [7449423635]=3}

local function getQuestText()
    local main = player:FindFirstChild("PlayerGui") and player.PlayerGui:FindFirstChild("Main")
    local quest = main and main:FindFirstChild("Quest")
    if not (quest and quest.Visible) then return nil end
    local container = quest:FindFirstChild("Container")
    local title = container and container:FindFirstChild("QuestTitle")
    local label = title and title:FindFirstChild("Title")
    return label and label.Text or ""
end

local function normalizeName(name)
    return tostring(name):lower():gsub("[^a-z0-9]", "")
end

local function questMatches(text, mobName)
    if not text then return false end
    local normalizedText = normalizeName(text)
    local normalizedMob = normalizeName(mobName)
    return normalizedText:find(normalizedMob, 1, true) ~= nil
        or normalizedText:find(normalizedMob:sub(1, math.min(9, #normalizedMob)), 1, true) ~= nil
end

local function questRemote()
    local remotes = ReplicatedStorage:FindFirstChild("Remotes")
    return remotes and remotes:FindFirstChild("CommF_")
end

local function moveToward(root, destination, reach)
    local delta = destination - root.Position
    local magnitude = delta.Magnitude
    if magnitude <= (reach or 16) then return true end
    -- Um passo por ciclo, evitando saltos longos em um unico frame.
    local step = math.min(magnitude, settings.safeMode and 18 or 75)
    local nextPosition = root.Position + delta.Unit * step
    if settings.safeMode then
        local char = player.Character
        local human = char and char:FindFirstChildOfClass("Humanoid")
        if human then human:MoveTo(nextPosition) end
    else
        root.CFrame = CFrame.lookAt(nextPosition, nextPosition + root.CFrame.LookVector)
    end
    return false
end

local function setFarmStatus(message)
    farmState.message = message
    if farmStateLabel then farmStateLabel.Text = message end
end

local function findMobRootForQuest(quest, root)
    local enemyFolder = workspace:FindFirstChild("Enemies")
    if not enemyFolder or not root then return nil end
    local nearest, bestDistance = nil, 550
    for _, mob in ipairs(enemyFolder:GetChildren()) do
        if mob:IsA("Model") and mob.Name:lower():find(quest[3]:lower(), 1, true) then
            local humanoid = mob:FindFirstChildOfClass("Humanoid")
            local part = mob:FindFirstChild("HumanoidRootPart")
            if humanoid and humanoid.Health > 0 and part then
                local distance = (part.Position - root.Position).Magnitude
                if distance < bestDistance then
                    nearest, bestDistance = part, distance
                end
            end
        end
    end
    return nearest
end

local function refreshFarmUiAtCap()
    settings.autoFarm = false
    if farmSwitch and farmDot then
        tween(farmSwitch, {BackgroundColor3 = C.raised2})
        tween(farmDot, {Position = UDim2.fromOffset(4, 4), BackgroundColor3 = C.muted})
    end
    syncToggles()
    setFarmStatus("Objetivo atingido: Lv. 2800")
end

local attackClick
local function farmTick()
    local healthy, why = safetyCheck()
    if not healthy then setFarmStatus("Farm parado: " .. tostring(why)) return end
    local lv = tonumber(readData("Level"))
    if not lv then setFarmStatus("Aguardando nivel do personagem") return end
    if lv >= MAX_FARM_LEVEL then refreshFarmUiAtCap() return end

    local quest = questForLevel(lv)
    if not quest then setFarmStatus("Sem quest mapeada para o nivel " .. lv) return end
    farmState.target = quest
    local lvInfo = QUEST_BY_LEVEL[math.floor(lv)]
    farmQuestLabel.Text = string.format("Lv. %d/%d | %s | proxima: %d", lv, MAX_FARM_LEVEL, quest[3],
        lvInfo and lvInfo.nextQuestLevel or MAX_FARM_LEVEL)

    local world = seaByPlace[game.PlaceId]
    if world ~= quest[2] then
        setFarmStatus("Entre no " .. tostring(quest[2]) .. "o Mar para continuar")
        return
    end

    local character = player.Character
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    local root = character and character:FindFirstChild("HumanoidRootPart")
    if not (humanoid and root) or humanoid.Health <= 0 then
        setFarmStatus("Aguardando respawn") return
    end
    if not farmState.stuckPos then
        farmState.stuckPos = root.Position
        farmState.stuckAt = os.clock()
    end
    if (root.Position - farmState.stuckPos).Magnitude > 18 then
        farmState.stuckPos = root.Position
        farmState.stuckAt = os.clock()
    elseif os.clock() - farmState.stuckAt > 85 then
        pauseAutomation("Sem progresso de movimento em 85s")
        return
    end

    if quest[1] >= 2600 and root.Position.Y > -800 then
        setFarmStatus("Entre na Submerged Island (libere o Tyrant primeiro)")
        return
    end

    if settings.autoQuest then
        local questText = getQuestText()
        if questText and not questMatches(questText, quest[3]) then
            if os.clock() >= farmState.retryAt then
                local remote = questRemote()
                if remote then guardedInvoke("AbandonQuest") end
                farmState.retryAt = os.clock() + 4
            end
            setFarmStatus("Trocando quest antiga")
            return
        end
        if not questText then
            if not moveToward(root, quest[6], 22) then
                setFarmStatus("Indo ao NPC da missao")
                return
            end
            if os.clock() >= farmState.retryAt then
                local remote = questRemote()
                if remote then
                    local ok = guardedInvoke("StartQuest", quest[4], quest[5])
                    setFarmStatus(ok and "Missao solicitada" or "Falha ao solicitar missao")
                else
                    setFarmStatus("Remote de missao indisponivel")
                end
                farmState.retryAt = os.clock() + 3.5
            end
            return
        end
    end

    local enemy = findMobRootForQuest(quest, root)
    if not enemy then
        if moveToward(root, quest[7], 90) then
            setFarmStatus("Aguardando aparecer: " .. quest[3])
        else
            setFarmStatus("Indo ao local: " .. quest[3])
        end
        return
    end
    if settings.autoEquip then equipSelected() end
    moveToward(root, enemy.Position + Vector3.new(0, 4, 6), 9)
    setFarmStatus("Farmando " .. quest[3])
    attackClick()
end

attackClick = function()
    if os.clock() < (farmState.nextAttack or 0) then return end
    farmState.nextAttack = os.clock() + math.max(0.85, settings.farmInterval)
    if settings.safeMode then
        local character = player.Character
        local held = character and character:FindFirstChildOfClass("Tool")
        if held then pcall(function() held:Activate() end) end
        return
    end
    local localMouseClick = (type(mouse1click) == "function") and mouse1click or nil
    if localMouseClick then
        pcall(localMouseClick)
    else
        pcall(function()
            local camera = workspace.CurrentCamera
            VirtualUser:CaptureController()
            local clickPosition = Vector2.new(500, 350)
            VirtualUser:Button1Down(clickPosition, camera.CFrame)
            VirtualUser:Button1Up(clickPosition, camera.CFrame)
        end)
    end
end

--[[
    MODULOS ADICIONAIS - v2.0
    Recursos de estabilidade / diagnostico: nao contornam moderacao, bans ou anti-cheat.
    Todos os modos automaticos iniciam desligados. Nenhum endpoint remoto e carregado.
]]
local recentLogs = {}
local logLabel
pushLog = function(tag, message)
    local entry = string.format("[%s] %-10s %s", os.date("%H:%M:%S"), tostring(tag), tostring(message))
    table.insert(recentLogs, 1, entry)
    while #recentLogs > 70 do table.remove(recentLogs) end
    if logLabel then
        local entries = {}
        for i = 1, math.min(#recentLogs, 22) do entries[i] = recentLogs[i] end
        logLabel.Text = table.concat(entries, "\n")
    end
end

local function getPingMs()
    local ok, value = pcall(function()
        local s = Stats.Network.ServerStatsItem["Data Ping"]:GetValueString()
        return tonumber(s:match("[%d.]+"))
    end)
    if ok then return value end
    return nil
end

local faultCount, lastFaultAt = 0, 0
local throttleTimes = {}
local callsByName = {StartQuest=4,AbandonQuest=4,Buso=16,Ken=18,AddPoint=9}
local isSessionPaused = false
pauseAutomation = function(reason)
    local active = settings.autoFarm or settings.autoBoss or settings.autoChest or settings.autoFruit or settings.autoRaid
    settings.autoFarm = false
    settings.autoBoss = false
    settings.autoChest = false
    settings.autoFruit = false
    settings.autoRaid = false
    syncToggles()
    isSessionPaused = true
    if active then
        setFarmStatus("Pausado: " .. tostring(reason))
        pushLog("SEGURANCA", reason)
        notify("Automacoes interrompidas: " .. tostring(reason))
    end
end

safetyCheck = function()
    if isSessionPaused then return false, "Pausa manual/seguranca" end
    if settings.pauseOnLag then
        local ping = getPingMs()
        if ping and ping > settings.maxPing then
            pauseAutomation("Ping alto: " .. math.floor(ping) .. " ms")
            return false, "Ping acima do limite"
        end
    end
    local character = player.Character
    local human = character and character:FindFirstChildOfClass("Humanoid")
    if human and human.MaxHealth > 0 and settings.pauseOnLowHealth then
        if human.Health / human.MaxHealth < 0.15 then
            pauseAutomation("Vida baixa")
            return false, "Vida baixa"
        end
    end
    return true
end

guardedInvoke = function(action, ...)
    if not alive then return false, "Hub fechado" end
    local now = os.clock()
    local delayFor = math.max(1.3, settings.remoteCooldown, callsByName[action] or 0)
    if (throttleTimes[action] or -math.huge) + delayFor > now then
        return false, "Aguardando limite de chamadas"
    end
    local safe, reason = safetyCheck()
    if not safe then return false, reason end
    local remote = questRemote()
    if not remote or not remote:IsA("RemoteFunction") then
        return false, "Remote indisponivel"
    end
    throttleTimes[action] = now
    local args = {...}
    local ok, result = pcall(function() return remote:InvokeServer(action, table.unpack(args)) end)
    if not ok then
        if now - lastFaultAt > 50 then faultCount = 0 end
        lastFaultAt = now
        faultCount = faultCount + 1
        pushLog("ERRO", action .. ": " .. tostring(result):sub(1, 100))
        if faultCount >= 3 and settings.pauseOnErrors then pauseAutomation("Tres falhas consecutivas") end
        return false, tostring(result)
    end
    faultCount = 0
    return true, result
end

local function guardedFire(action, ...)
    if not alive then return false, "Hub fechado" end
    local now = os.clock()
    local minInterval = math.max(1.3, settings.remoteCooldown, callsByName[action] or 0)
    if now - (throttleTimes[action] or -math.huge) < minInterval then
        return false, "Limite de chamadas"
    end
    local okToAct, why = safetyCheck()
    if not okToAct then return false, why end
    local remotes = ReplicatedStorage:FindFirstChild("Remotes")
    local remote = remotes and remotes:FindFirstChild("CommE")
    if not remote or not remote:IsA("RemoteEvent") then
        return false, "Evento do jogo indisponivel"
    end
    throttleTimes[action] = now
    local args = {...}
    local success, errorText = pcall(function()
        remote:FireServer(action, table.unpack(args))
    end)
    if not success then
        pushLog("ERRO", action .. ": " .. tostring(errorText):sub(1, 85))
    end
    return success, errorText
end

