local currentBossLabel, bossStatusLabel, bossIndex = nil, nil, 1
local function updateBossLabel()
    if not currentBossLabel then return end
    bossIndex = math.clamp(bossIndex, 1, math.max(1, #BOSS_CATALOG))
    local row = BOSS_CATALOG[bossIndex]
    if row then currentBossLabel.Text = row[1] .. "  (" .. bossIndex .. "/" .. #BOSS_CATALOG .. ")" end
end

local function findBoss()
    local enemies = workspace:FindFirstChild("Enemies")
    if not enemies or not BOSS_CATALOG[bossIndex] then return end
    local expected = BOSS_CATALOG[bossIndex][1]:gsub("%s*%[.*", ""):lower()
    for _, model in ipairs(enemies:GetChildren()) do
        if model:IsA("Model") and model.Name:lower():find(expected, 1, true) then
            local hum = model:FindFirstChildOfClass("Humanoid")
            local root = model:FindFirstChild("HumanoidRootPart")
            if hum and hum.Health > 0 and root then return root, hum end
        end
    end
end

