-- Os seguintes coletores leem o que o cliente ja recebeu; nao consultam APIs externas.
local function closestObject(predicate, maxDistance)
    local root = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
    if not root then return nil end
    local candidate, bestDistance = nil, maxDistance or 180
    local seen = 0
    for _, v in ipairs(workspace:GetDescendants()) do
        seen = seen + 1
        if seen > 7000 then break end
        if predicate(v) then
            local part = findPart(v)
            if part then
                local distance = (part.Position-root.Position).Magnitude
                if distance < bestDistance then
                    candidate, bestDistance = part, distance
                end
            end
        end
    end
    return candidate, bestDistance
end
local function isFruit(v)
    return v:IsA("Tool") and v.Name:lower():find("fruit",1,true) ~= nil
end
local function isChest(v)
    return v:IsA("BasePart") and v.Name:lower():find("chest",1,true) ~= nil
end

local trackedEffects = setmetatable({}, {__mode="k"})
local function setFPSBoost(active)
    if active then
        local processed = 0
        for _, effect in ipairs(workspace:GetDescendants()) do
            if processed >= 4500 then break end
            processed = processed + 1
            if effect:IsA("ParticleEmitter") or effect:IsA("Trail") or effect:IsA("Beam") then
                if trackedEffects[effect] == nil then trackedEffects[effect] = effect.Enabled end
                pcall(function() effect.Enabled = false end)
            end
        end
    else
        for effect, enabled in pairs(trackedEffects) do
            pcall(function() effect.Enabled = enabled end)
            trackedEffects[effect] = nil
        end
    end
end

local function tickBoss()
    if settings.autoBoss then
        local ok = safetyCheck()
        if not ok then return end
    end
    local enemy, human = findBoss()
    if not enemy then
        if bossStatusLabel then bossStatusLabel.Text = "Chefe nao apareceu ou fora da area carregada" end
        return
    end
    if bossStatusLabel then bossStatusLabel.Text = string.format("Visivel! HP %.0f / %.0f", human.Health, human.MaxHealth) end
    if settings.autoBoss then
        local root = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
        if root then
            if settings.autoEquip then equipSelected() end
            moveToward(root, enemy.Position + Vector3.new(0,4,5), 10)
            attackClick()
        end
    end
end

local function tickRaid()
    if not (settings.autoRaid or settings.raidTracker) then return end
    local enemies = workspace:FindFirstChild("Enemies")
    local count = enemies and #enemies:GetChildren() or 0
    -- A deteccao da raid e heuristica e nao promete reconhecer todas as versoes.
    local raidTimer = player.PlayerGui:FindFirstChild("Main")
    local hasTimer = raidTimer and raidTimer:FindFirstChild("Timer", true)
    if raidLabel then
        raidLabel.Text = (hasTimer and hasTimer.Visible and "Evento de raid possivel" or "Raid nao confirmada")
            .. "  •  NPCs carregados: " .. tostring(count)
    end
    if settings.autoRaid and hasTimer and hasTimer.Visible and enemies then
        local root = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
        if not root then return end
        local nearest, shortest = nil, 170
        for _, mob in ipairs(enemies:GetChildren()) do
            local human = mob:FindFirstChildOfClass("Humanoid")
            local part = mob:FindFirstChild("HumanoidRootPart")
            if human and human.Health > 0 and part then
                local dist = (part.Position-root.Position).Magnitude
                if dist < shortest then nearest, shortest = part, dist end
            end
        end
        if nearest then
            local ok = safetyCheck()
            if not ok then return end
            moveToward(root, nearest.Position + Vector3.new(0,4,5), 10)
            attackClick()
        end
    end
end

local SEA_EVENT_NAMES = {
    "Sea Beast", "Terrorshark", "Mirage Island", "Kitsune Island", "Prehistoric Island",
    "Leviathan", "Frozen Dimension", "Ship Raid", "Terror Shark", "Rumbling Waters",
}
local function tickSeaEvent()
    if not settings.seaEventTracker or not seaEventLabel then return end
    local results = {}
    local scanned = 0
    for _, obj in ipairs(workspace:GetDescendants()) do
        scanned = scanned + 1
        if scanned > 6500 then break end
        if obj:IsA("Model") then
            local label = obj.Name:lower()
            for _, keyword in ipairs(SEA_EVENT_NAMES) do
                if label:find(keyword:lower(), 1, true) then
                    results[keyword] = true
                    break
                end
            end
        end
    end
    local formatted = {}
    for name in pairs(results) do table.insert(formatted, name) end
    table.sort(formatted)
    seaEventLabel.Text = #formatted > 0 and table.concat(formatted, ", ") or "Nenhum evento reconhecido no mapa"
end

local function tickCollect()
    if not (settings.autoChest or settings.autoFruit) then return end
    local ok = safetyCheck()
    if not ok then return end
    local root = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
    if not root then return end
    local part, distance
    if settings.autoFruit then part, distance = closestObject(isFruit, 200) end
    if not part and settings.autoChest then part, distance = closestObject(isChest, 180) end
    if part then moveToward(root, part.Position, 6) end
end

