    while alive do
        pcall(function()
            if settings.autoAura then guardedInvoke("Buso") end
            if settings.autoInstinct then guardedFire("Ken", true) end
            if settings.autoStats then
                local data = player:FindFirstChild("Data")
                local stats = data and data:FindFirstChild("Points")
                if stats and stats.Value > 0 then
                    guardedInvoke("AddPoint", settings.statCategory, math.min(3, stats.Value))
                end
            end
        end)
        task.wait(7)
    end
end)
