    while alive do
        pcall(function()
            local root = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
            local quest = questForLevel(tonumber(readData("Level")) or 1)
            if quest and routeLabel then
                routeLabel.Text = string.format("Lv. %s: %s / %s", tostring(quest[1]), quest[3], quest[4])
            end
            if root and coordsLabel then
                coordsLabel.Text = settings.showCoordinates and tostring(root.Position) or "Coordenadas ocultas"
            end
            local bpart = findBoss()
            if bossStatusLabel and not settings.autoBoss then
                bossStatusLabel.Text = bpart and "Boss presente na area" or "Boss nao identificado"
            end
            local fruit, fd = closestObject(isFruit, 500)
            local chest, cd = closestObject(isChest, 500)
            if nearItemsLabel then
                nearItemsLabel.Text = (fruit and ("Fruta a " .. math.floor(fd) .. " studs") or "Sem fruta perto")
                    .. "  |  " .. (chest and ("Bau a " .. math.floor(cd) .. " studs") or "Sem bau perto")
            end
        end)
        task.wait(6)
    end
end)
