    while alive do
        currentFrames, frames = frames, 0
        local ping = "--"
        pcall(function() ping = Stats.Network.ServerStatsItem["Data Ping"]:GetValueString() end)
        pcall(function()
            local frame = fpsValue
            -- fpsValue e o container; atualiza-se somente seu TextLabel descritivo.
            local labels = frame:GetChildren()
            for _, label in ipairs(labels) do
