keyTitle.ZIndex = 22
local keyTip = textLabel(keyCard, "Insira sua chave para abrir o painel", 12, C.muted)
keyTip.Position = UDim2.fromOffset(22, 53)
keyTip.Size = UDim2.new(1, -44, 0, 22)
keyTip.ZIndex = 22
local keyBox = round(make("TextBox", {
    Position = UDim2.fromOffset(22, 87),
    Size = UDim2.new(1, -44, 0, 43),
    BackgroundColor3 = C.raised,
    Text = "",
    PlaceholderText = "Sua chave de acesso",
