keyError.ZIndex = 22
local function tryUnlock()
    if keyBox.Text == ACCESS_KEY then
        keyOverlay:Destroy()
        notify("FrioHub pronto.")
        pushLog("ACESSO", "Chave local validada")
    else
        keyError.Text = "Chave incorreta."
    end
end
connect(enter.MouseButton1Click, tryUnlock)
connect(keyBox.FocusLost, function(pressedEnter) if pressedEnter then tryUnlock() end end)

